# Create model
model = gp.Model("TransportationProblem")

# Cities
C = [0, 1, 2, 3, 4, 5, 6]

# Net demand/supply (positive = demand, negative = supply)
d = {0: 5, 1: -1, 2: 2, 3: -2, 4: -4, 5: 1, 6: -1}

# Transportation costs
c = {
    0: {1: 4, 2: 4, 3: 2, 4: 3, 5: 3, 6: 2},
    1: {0: 3, 2: 2, 3: 2, 4: 4, 5: 3, 6: 4},
    2: {0: 4, 1: 2, 3: 4, 4: 3, 5: 4, 6: 3},
    3: {0: 4, 1: 4, 2: 2, 4: 4, 5: 3, 6: 2},
    4: {0: 3, 1: 2, 2: 4, 3: 2, 5: 4, 6: 3},
    5: {0: 4, 1: 2, 2: 3, 3: 2, 4: 3, 6: 3},
    6: {0: 4, 1: 2, 2: 4, 3: 2, 4: 3, 5: 2}
}

# Transportation link capacities
u = {
    0: {1: 7, 2: 4, 3: 9, 4: 9, 5: 10, 6: 10},
    1: {0: 8, 2: 5, 3: 3, 4: 3, 5: 4, 6: 9},
    2: {0: 5, 1: 8, 3: 6, 4: 5, 5: 10, 6: 8},
    3: {0: 7, 1: 6, 2: 10, 4: 3, 5: 6, 6: 9},
    4: {0: 10, 1: 10, 2: 7, 3: 6, 5: 4, 6: 3},
    5: {0: 5, 1: 10, 2: 3, 3: 3, 4: 9, 6: 10},
    6: {0: 7, 1: 3, 2: 9, 3: 9, 4: 6, 5: 8}
}

# City receiving capacities
r = {0: 19, 1: 13, 2: 7, 3: 8, 4: 11, 5: 12, 6: 14}

# Decision variables
x = model.addVars([(i,j) for i in C for j in C if i != j], vtype=GRB.CONTINUOUS, name="x")

# Objective function
model.setObjective(gp.quicksum(c[i][j] * x[i,j] for i in C for j in C if i != j), GRB.MINIMIZE)

# Flow balance constraints
for i in C:
    model.addConstr(gp.quicksum(x[j,i] for j in C if j != i) - gp.quicksum(x[i,j] for j in C if j != i) == d[i], f"flow_balance_{i}")

# Receiving capacity constraints
for i in C:
    model.addConstr(gp.quicksum(x[j,i] for j in C if j != i) <= r[i], f"receive_cap_{i}")

# Transportation link capacity constraints
for i in C:
    for j in C:
        if i != j:
            model.addConstr(x[i,j] <= u[i][j], f"link_cap_{i}_{j}")

# Optimize
model.optimize()

# Print solution
if model.status == GRB.OPTIMAL:
    print("Optimal solution found:")
    for i in C:
        for j in C:
            if i != j and x[i,j].x > 0:
                print(f"Transport {x[i,j].x} units from city {i} to city {j}")
    print(f"Total transportation cost: {model.objVal}")
else:
    print("No optimal solution found")
