# Parameters
t = {0: 69, 1: 57, 2: 67, 3: 75}
e = {i: 55 for i in I}
l = {i: 75 for i in I}
p_e = {0: 29, 1: 35, 2: 26, 3: 25}
p_l = {0: 30, 1: 28, 2: 30, 3: 34}
s = {
    (0, 1): 3, (1, 0): 4,
    (0, 2): 3, (2, 0): 4,
    (0, 3): 3, (3, 0): 4,
    (1, 2): 4, (2, 1): 3,
    (1, 3): 4, (3, 1): 4,
    (2, 3): 3, (3, 2): 3
}

# Decision variables
x = model.addVars(I, lb=e, ub=l, name="x")
y = model.addVars(I, I, vtype=GRB.BINARY, name="y")
z_e = model.addVars(I, lb=0, name="z_e")
z_l = model.addVars(I, lb=0, name="z_l")

# Objective
model.setObjective(
    gp.quicksum(p_e[i] * z_e[i] + p_l[i] * z_l[i] for i in I),
    GRB.MINIMIZE
)

# Constraints
# Landing time bounds are handled by variable bounds

# Early and late landing time definitions
model.addConstrs(
    z_e[i] >= t[i] - x[i] for i in I
)
model.addConstrs(
    z_l[i] >= x[i] - t[i] for i in I
)

# Separation constraints
M = 20  # Large constant
for i in I:
    for j in I:
        if i != j:
            model.addConstr(
                x[i] + s[i, j] <= x[j] + M * (1 - y[i, j])
            )
            model.addConstr(
                x[j] + s[j, i] <= x[i] + M * y[i, j]
            )

# Order consistency
for i in I:
    for j in I:
        if i < j:
            model.addConstr(
                y[i, j] + y[j, i] == 1
            )

# Solve
model.optimize()

# Print solution
if model.status == GRB.OPTIMAL:
    print("Optimal solution found:")
    for i in I:
        print(f"Aircraft {i}: lands at {x[i].X}, early {z_e[i].X}, late {z_l[i].X}")
    print(f"Total penalty cost: {model.ObjVal}")
else:
    print("No optimal solution found")
