from gurobipy import Model, GRB

# Create model
m = Model("CarAssignment")

# Participants and cars
P = range(7)  # participant_0 to participant_6
C = range(6)   # car_0 to car_5

# Preference matrix
A = {
    0: {5: 1},
    1: {1: 1},
    2: {3: 1, 4: 1},
    3: {0: 1, 1: 1, 2: 1},
    4: {3: 1, 5: 1},
    5: {},
    6: {0: 1, 3: 1}
}

# Decision variables
x = {}
for p in P:
    for c in C:
        x[p, c] = m.addVar(vtype=GRB.BINARY, name=f"x_{p}_{c}")

# Objective: maximize total assignments
m.setObjective(sum(A[p].get(c, 0) * x[p, c] for p in P for c in C), GRB.MAXIMIZE)

# Constraints
# Each participant assigned to at most one car
for p in P:
    m.addConstr(sum(x[p, c] for c in C) <= 1, name=f"participant_{p}_limit")

# Each car assigned to at most one participant
for c in C:
    m.addConstr(sum(x[p, c] for p in P) <= 1, name=f"car_{c}_limit")

# Assignments must respect preferences
for p in P:
    for c in C:
        if c not in A[p]:
            m.addConstr(x[p, c] == 0, name=f"preference_{p}_{c}")

# Optimize
m.optimize()

# Print solution
if m.status == GRB.OPTIMAL:
    print("Optimal assignments:")
    for p in P:
        for c in C:
            if x[p, c].x > 0.5:
                print(f"Participant {p} -> Car {c}")
    print(f"Total assignments: {m.objVal}")
else:
    print("No optimal solution found")
