from gurobipy import Model, GRB

# Create a new model
m = Model("BinPacking")

# Sets
I = range(7)  # Items 0 to 6
B = range(7)  # Bins 0 to 6

# Parameters
w = [31, 35, 27, 31, 28, 33, 33]  # Weights of items
C = 100  # Bin capacity

# Decision variables
x = {}
for i in I:
    for b in B:
        x[i, b] = m.addVar(vtype=GRB.BINARY, name=f"x_{i}_{b}")

y = {}
for b in B:
    y[b] = m.addVar(vtype=GRB.BINARY, name=f"y_{b}")

# Objective: Minimize the number of bins used
m.setObjective(sum(y[b] for b in B), GRB.MINIMIZE)

# Constraints
# Assignment constraint: Each item is assigned to exactly one bin
for i in I:
    m.addConstr(sum(x[i, b] for b in B) == 1, name=f"Assign_{i}")

# Capacity constraint: Total weight in a bin <= C if the bin is used
for b in B:
    m.addConstr(sum(w[i] * x[i, b] for i in I) <= C * y[b], name=f"Cap_{b}")

# Optimize the model
m.optimize()

# Print the solution
if m.status == GRB.OPTIMAL:
    print(f"Optimal number of bins used: {m.objVal}")
    for b in B:
        if y[b].x > 0.5:
            print(f"Bin {b} contains items:", end=" ")
            for i in I:
                if x[i, b].x > 0.5:
                    print(f"Item {i} (w={w[i]})", end=" ")
            print()
else:
    print("No optimal solution found.")
