    0: {0: 32, 1: 27, 2: 27, 3: 20},
    1: {0: 26, 1: 27, 2: 37, 3: 37},
    2: {0: 41, 1: 20, 2: 43, 3: 26}
}
max_inventory = 50
final_inventory = 10

# Model
model = gp.Model("Production_Planning")

# Decision Variables
prod = model.addVars(products, periods, name="Production")
inv = model.addVars(products, periods, name="Inventory")
sales = model.addVars(products, periods, name="Sales")

# Objective Function
model.setObjective(
    gp.quicksum(profit[p] * sales[p, t] for p in products for t in periods) -
    gp.quicksum(holding_cost * inv[p, t] for p in products for t in periods),
    GRB.MAXIMIZE
)

# Constraints
# Inventory Balance
for p in products:
    model.addConstr(prod[p, 0] == sales[p, 0] + inv[p, 0], f"Inv_Balance_{p}_0")

