    for t in periods[1:]:
        model.addConstr(
            inv[p, t-1] + prod[p, t] == sales[p, t] + inv[p, t],
            f"Inv_Balance_{p}_{t}"
        )

# Machine Capacity
for m in machines:
    for t in periods:
        model.addConstr(
            gp.quicksum(machine_hours[m][p] * prod[p, t] for p in products) <= capacity[m][t],
            f"Machine_Capacity_{m}_{t}"
        )

