    for t in periods:
        model.addConstr(sales[p, t] <= max_sales[p][t], f"Sales_Limit_{p}_{t}")

# Inventory Limits
for p in products:
    for t in periods:
        model.addConstr(inv[p, t] <= max_inventory, f"Inv_Limit_{p}_{t}")

# Final Inventory Requirement
for p in products:
    model.addConstr(inv[p, 3] == final_inventory, f"Final_Inv_{p}")

# Solve
model.optimize()

