    for p in P:
        for l in L:
            for t in T:
                if y[p, l, t].x > 0:
                    print(f"{y[p, l, t].x} idle planes of type {p} at location {l} at start of period {t}")
    print(f"Total cost: {model.objVal}")
else:
    print("No optimal solution found.")
