    0: [254, 200, 137, 58],
    1: [273, 195, 116, 60]
}

# Decision variables
x = model.addVars(products, periods, name="Production")
y = model.addVars(products, periods, vtype=GRB.BINARY, name="Setup")
I = model.addVars(products, periods, name="Inventory")

# Objective function
model.setObjective(
    gp.quicksum(
        production_cost[p][t] * x[p, t] + setup_cost[p][t] * y[p, t] + holding_cost[p][t] * I[p, t]
        for p in products for t in periods
    ),
    GRB.MINIMIZE
)

# Constraints
# Demand fulfillment
for p in products:
    for t in periods:
        model.addConstr(
            gp.quicksum(x[p, k] for k in range(t + 1)) + I[p, t] >= cum_demand[p][t],
            f"Demand_{p}_{t}"
