m = Model("Hub_Supply_Optimization")

# Hubs
hubs = [0, 1, 2, 3, 4, 5, 6]

# Transportation costs (c[i][j])
cost = {
    0: {1: 14, 2: 10, 3: 12, 4: 10, 5: 14, 6: 13},
    1: {0: 14, 2: 15, 3: 12, 4: 12, 5: 12, 6: 10},
    2: {0: 14, 1: 12, 3: 11, 4: 12, 5: 11, 6: 13},
    3: {0: 12, 1: 14, 2: 14, 4: 11, 5: 12, 6: 11},
    4: {0: 14, 1: 10, 2: 11, 3: 10, 5: 15, 6: 15},
    5: {0: 10, 1: 10, 2: 11, 3: 15, 4: 10, 6: 10},
    6: {0: 12, 1: 14, 2: 12, 3: 14, 4: 11, 5: 13}
}

# Decision variables: x[i][j] = 1 if route from i to j is used
x = {}
for i in hubs:
    for j in hubs:
        if j in cost[i]:
            x[i, j] = m.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")

# Objective: minimize total cost
m.setObjective(sum(cost[i][j] * x[i, j] for i in hubs for j in hubs if j in cost[i]), GRB.MINIMIZE)

# Flow conservation constraints
# Hub 0: source (net supply of 1)
m.addConstr(sum(x[0, j] for j in hubs if j in cost[0]) - sum(x[i, 0] for i in hubs if 0 in cost[i]) == 1, "source")

# Hub 6: sink (net demand of 1)
m.addConstr(sum(x[i, 6] for i in hubs if 6 in cost[i]) - sum(x[6, j] for j in hubs if j in cost[6]) == 1, "sink")

# Intermediate hubs: flow conservation
for k in [1, 2, 3, 4, 5]:
    m.addConstr(sum(x[i, k] for i in hubs if k in cost[i]) == sum(x[k, j] for j in hubs if j in cost[k]), f"hub_{k}")

# Optimize
m.optimize()

# Print solution
if m.status == GRB.OPTIMAL:
    print(f"Total cost: {m.objVal}")
    for i in hubs:
        for j in hubs:
            if j in cost[i] and x[i, j].x > 0.5:
