    [316, 0, 333, 329],
    [253, 322, 0, 282],
    [305, 281, 268, 0]
]

# Decision variables
x = {}
for i in Cities:
    for j in Cities:
        if i != j:
            x[i, j] = model.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")

u = {}
for k in [1, 2, 3]:
    u[k] = model.addVar(vtype=GRB.INTEGER, lb=1, ub=3, name=f"u_{k}")

# Objective function
model.setObjective(
    gp.quicksum(distance[i][j] * x[i, j] for i in Cities for j in Cities if i != j),
    GRB.MINIMIZE
)

# Constraints
