for j in Cities:
    model.addConstr(
        gp.quicksum(x[i, j] for i in Cities if i != j) == 1,
        name=f"enter_{j}"
    )

# Each city exited exactly once
for i in Cities:
    model.addConstr(
        gp.quicksum(x[i, j] for j in Cities if j != i) == 1,
        name=f"exit_{i}"
    )

# Subtour elimination
for i in [1, 2, 3]:
    for j in [1, 2, 3]:
        if i != j:
            model.addConstr(
                u[i] - u[j] + (n - 1) * x[i, j] <= (n - 2),
                name=f"subtour_{i}_{j}"
            )

