d = {
    0: {1: 156, 2: 160, 3: 151, 4: 159, 5: 163},
    1: {0: 161, 2: 158, 3: 154, 4: 155, 5: 152},
    2: {0: 155, 1: 165, 3: 157, 4: 158, 5: 150},
    3: {0: 155, 1: 155, 2: 168, 4: 163, 5: 166},
    4: {0: 161, 1: 164, 2: 166, 3: 161, 5: 158},
    5: {0: 167, 1: 152, 2: 156, 3: 154, 4: 162},
}

# Create the model
model = gp.Model("TSP")

# Decision variables
x = {}
for i in cities:
    for j in cities:
        if i != j:
            x[i, j] = model.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")

u = {}
for i in cities:
    u[i] = model.addVar(vtype=GRB.INTEGER, lb=0, ub=n-1, name=f"u_{i}")

# Objective function
model.setObjective(
    gp.quicksum(d[i][j] * x[i, j] for i in cities for j in cities if i != j),
    GRB.MINIMIZE
)

# Constraints
# Each city has exactly one incoming route
for j in cities:
    model.addConstr(
        gp.quicksum(x[i, j] for i in cities if i != j) == 1,
        name=f"incoming_{j}"
    )

# Each city has exactly one outgoing route
for i in cities:
    model.addConstr(
        gp.quicksum(x[i, j] for j in cities if j != i) == 1,
        name=f"outgoing_{i}"
    )

# Subtour elimination constraints
for i in cities:
    for j in cities:
        if i != j and i != 0 and j != 0:
            model.addConstr(
                u[i] - u[j] + n * x[i, j] <= n - 1,
                name=f"subtour_{i}_{j}"
            )

# Position variable for starting city
model.addConstr(u[0] == 0, name="start_position")

# Optimize the model
model.optimize()

# Print the solution
