    print("Optimal route:")
    for i in cities:
        for j in cities:
            if i != j and x[i, j].X > 0.5:
                print(f"City {i} -> City {j} (Distance: {d[i][j]})")
    print(f"Total distance: {model.ObjVal}")
else:
    print("No solution found")
