# Create model
model = gp.Model("PlaneDeployment")

# Sets
P = [0, 1, 2]  # Plane types
L = [0, 1]     # Locations
T = [1, 2]     # Time periods

# Parameters
c = {0: 5, 1: 6, 2: 5}  # Cost per flight
cap = {0: 89, 1: 90, 2: 87}  # Capacity per plane
demand = {
    (0, 1, 2): 13,
    (1, 0, 1): 16,
    (1, 0, 2): 6
}
max_p = 2  # Maximum number of planes per type
restrict = {
    (0, 0, 1, 1): 0,
    (0, 0, 1, 2): 2,
    (0, 1, 0, 1): 2,
    (0, 1, 0, 2): 2,
    (1, 0, 1, 1): 2,
    (1, 0, 1, 2): 2,
    (1, 1, 0, 1): 2,
    (1, 1, 0, 2): 2,
    (2, 0, 1, 1): 2,
    (2, 0, 1, 2): 2,
    (2, 1, 0, 1): 2,
    (2, 1, 0, 2): 2
}

# Decision Variables
x = model.addVars(P, L, L, T, vtype=GRB.INTEGER, name="x")
y = model.addVars(P, L, T, vtype=GRB.INTEGER, name="y")

# Objective: Minimize total cost
model.setObjective(
    gp.quicksum(c[p] * x[p, l1, l2, t] for p in P for l1 in L for l2 in L for t in T),
    GRB.MINIMIZE
)

# Constraints
# Demand satisfaction
for l1 in L:
    for l2 in L:
        for t in T:
            if (l1, l2, t) in demand:
                model.addConstr(
                    gp.quicksum(cap[p] * x[p, l1, l2, t] for p in P) >= demand[l1, l2, t],
                    f"demand_{l1}_{l2}_{t}"
                )

# Fleet balance
for p in P:
    for l in L:
        for t in T:
            if t > 1:
                model.addConstr(
                    y[p, l, t] == y[p, l, t-1] + gp.quicksum(x[p, l_prime, l, t-1] for l_prime in L) - gp.quicksum(x[p, l, l_prime, t-1] for l_prime in L),
                    f"balance_{p}_{l}_{t}"
                )

# Initial fleet balance
for p in P:
    for l in L:
        model.addConstr(
            y[p, l, 1] == max_p - gp.quicksum(x[p, l, l_prime, 1] for l_prime in L),
            f"initial_{p}_{l}"
        )

# Operational restrictions
for p in P:
    for l1 in L:
        for l2 in L:
            for t in T:
                if (p, l1, l2, t) in restrict:
                    model.addConstr(
                        x[p, l1, l2, t] <= restrict[p, l1, l2, t],
                        f"restrict_{p}_{l1}_{l2}_{t}"
                    )

# Solve
model.optimize()

# Output solution
if model.status == GRB.OPTIMAL:
    print("Optimal solution found:")
    for p in P:
        for l1 in L:
            for l2 in L:
                for t in T:
                    if x[p, l1, l2, t].x > 0:
                        print(f"Deploy {x[p, l1, l2, t].x} planes of type {p} from {l1} to {l2} in period {t}")
    print(f"Total cost: {model.objVal}")
else:
    print("No optimal solution found")
