import gurobipy as gp
from gurobipy import GRB

# Create model
model = gp.Model("PowerGeneration")

# Sets
T = [0, 1, 2]  # Time periods
G = [0, 1]     # Generator types (0: Type 0, 1: Type 1)

# Parameters
base_cost = {0: 90, 1: 86}
var_cost = {0: 3, 1: 2}
startup_cost = {0: 390, 1: 400}
demand = {0: 204, 1: 202, 2: 203}
min_cap = {0: 30, 1: 30}
max_cap = {0: 147, 1: 147}
reserve = {0: 234.6, 1: 232.3, 2: 233.45}
max_gen = {0: 2, 1: 4}
max_startup = {0: 2, 1: 3}

# Decision variables
x = {}  # Number of generators of type g in period t
p = {}  # Power output of type g in period t
s = {}  # Startups of type g in period t

for g in G:
    for t in T:
        x[g, t] = model.addVar(vtype=GRB.INTEGER, name=f"x_{g}_{t}")
        p[g, t] = model.addVar(lb=0, vtype=GRB.CONTINUOUS, name=f"p_{g}_{t}")
        s[g, t] = model.addVar(vtype=GRB.INTEGER, name=f"s_{g}_{t}")

# Objective: Minimize total cost
model.setObjective(
    gp.quicksum(
        base_cost[g] * x[g, t] + var_cost[g] * p[g, t] + startup_cost[g] * s[g, t]
        for g in G for t in T
    ),
    GRB.MINIMIZE
)

# Constraints
for t in T:
    # Demand satisfaction
    model.addConstr(
        gp.quicksum(p[g, t] for g in G) >= demand[t],
        name=f"demand_{t}"
    )

    # Reserve requirements
    model.addConstr(
        gp.quicksum(max_cap[g] * x[g, t] for g in G) >= reserve[t],
        name=f"reserve_{t}"
    )

for g in G:
    for t in T:
        # Capacity limits
        model.addConstr(
            p[g, t] >= min_cap[g] * x[g, t],
            name=f"min_cap_{g}_{t}"
        )
        model.addConstr(
            p[g, t] <= max_cap[g] * x[g, t],
            name=f"max_cap_{g}_{t}"
        )

        # Generator limits
        model.addConstr(
            x[g, t] <= max_gen[g],
            name=f"max_gen_{g}_{t}"
        )

    # Startup logic (only for period 0)
    model.addConstr(
        s[g, 0] <= max_startup[g],
        name=f"max_startup_{g}_0"
    )

# Solve
model.optimize()

# Print solution
if model.status == GRB.OPTIMAL:
