    0: {1: 274, 2: 292, 3: 273, 4: 330},
    1: {0: 251, 2: 317, 3: 348, 4: 339},
    2: {0: 251, 1: 293, 3: 337, 4: 309},
    3: {0: 267, 1: 278, 2: 265, 4: 338},
    4: {0: 267, 1: 327, 2: 272, 3: 306}
}

# Create model
model = gp.Model("TSP")

# Decision variables
x = {}
for i in cities:
    for j in cities:
        if i != j:
            x[i, j] = model.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")

u = {}
for i in cities:
    u[i] = model.addVar(vtype=GRB.INTEGER, lb=1, ub=5, name=f"u_{i}")

# Objective: minimize total distance
model.setObjective(
    gp.quicksum(distance[i][j] * x[i, j] for i in cities for j in cities if i != j),
    GRB.MINIMIZE
)

