        N[g, t] = model.addVar(vtype=GRB.INTEGER, name=f"N_{g}_{t}")
        P[g, t] = model.addVar(vtype=GRB.CONTINUOUS, name=f"P_{g}_{t}")
        S[g, t] = model.addVar(vtype=GRB.INTEGER, name=f"S_{g}_{t}")

# Objective Function
model.setObjective(
    gp.quicksum(
        BaseCost[g] * N[g, t] + GenCost[g] * P[g, t] + StartupCost[g] * S[g, t]
        for g in G for t in T
    ),
    GRB.MINIMIZE
)

