    # Demand satisfaction
    model.addConstr(
        gp.quicksum(P[g, t] for g in G) >= Demand[t],
        name=f"Demand_{t}"
    )

    # Capacity buffer
    model.addConstr(
        gp.quicksum(MaxOutput[g] * N[g, t] for g in G) >= 1.15 * Demand[t],
        name=f"Buffer_{t}"
