    (0, 0): 1, (0, 1): 0,
    (1, 0): 1, (1, 1): 1,
    (2, 0): 0, (2, 1): 1,
    (3, 0): 1, (3, 1): 1,
    (4, 0): 0, (4, 1): 1,
    (5, 0): 1, (5, 1): 1,
    (6, 0): 1, (6, 1): 1
}

P = 100  # Penalty cost

# Skill availability: Employees 1, 5, 6 do not have Skill 0
has_skill = {
    0: True, 1: False, 2: True, 3: True, 4: True, 5: False, 6: False
}

# Decision Variables
x = model.addVars(E, R, S, K, vtype=GRB.BINARY, name="x")
u = model.addVars(R, S, K, vtype=GRB.INTEGER, name="u")

# Objective Function
model.setObjective(
    gp.quicksum(C[e, k] * x[e, r, s, k] for e in E for r in R for s in S for k in K) +
    gp.quicksum(P * u[r, s, k] for r in R for s in S for k in K),
    GRB.MINIMIZE
)

# Constraints
