    4: [(2, 'M0'), (1, 'M1')],
    5: [(1, 'M1'), (1, 'M0'), (1, 'M2')]
}

# Extract all operations and machines
operations = {}
machine_ops = {}  # {machine: [(job, op_index)]}
for job in jobs:
    for op_index, (p, machine) in enumerate(jobs[job]):
        operations[(job, op_index)] = (p, machine)
        if machine not in machine_ops:
            machine_ops[machine] = []
        machine_ops[machine].append((job, op_index))

# Big-M
M = sum(p for (job, op_index), (p, _) in operations.items())

# Decision variables
s = {}  # Start times
for (job, op_index) in operations:
    s[(job, op_index)] = model.addVar(lb=0, vtype=GRB.CONTINUOUS, name=f"s_{job}_{op_index}")

y = {}  # Binary variables for machine order
for machine in machine_ops:
    ops = machine_ops[machine]
    for i in range(len(ops)):
        for j in range(i + 1, len(ops)):
            y[(ops[i], ops[j])] = model.addVar(vtype=GRB.BINARY, name=f"y_{ops[i][0]}_{ops[i][1]}_{ops[j][0]}_{ops[j][1]}")

C_max = model.addVar(lb=0, vtype=GRB.CONTINUOUS, name="C_max")

# Objective
model.setObjective(C_max, GRB.MINIMIZE)

# Constraints
# Precedence constraints within each job
for job in jobs:
    for op_index in range(len(jobs[job]) - 1):
        model.addConstr(
            s[(job, op_index)] + jobs[job][op_index][0] <= s[(job, op_index + 1)],
            name=f"precedence_{job}_{op_index}"
        )

# Disjunctive constraints for shared machines
for machine in machine_ops:
    ops = machine_ops[machine]
    for i in range(len(ops)):
        for j in range(i + 1, len(ops)):
            op1 = ops[i]
            op2 = ops[j]
            p1 = operations[op1][0]
            p2 = operations[op2][0]
            model.addConstr(
                s[op1] + p1 <= s[op2] + M * (1 - y[(op1, op2)]),
                name=f"disjunctive1_{op1[0]}_{op1[1]}_{op2[0]}_{op2[1]}"
            )
            model.addConstr(
                s[op2] + p2 <= s[op1] + M * y[(op1, op2)],
                name=f"disjunctive2_{op1[0]}_{op1[1]}_{op2[0]}_{op2[1]}"
            )

# Makespan definition
for (job, op_index) in operations:
    model.addConstr(
        s[(job, op_index)] + operations[(job, op_index)][0] <= C_max,
        name=f"makespan_{job}_{op_index}"
    )

# Optimize
model.optimize()

# Print solution
if model.status == GRB.OPTIMAL:
    print(f"Optimal makespan: {C_max.X}")
    for (job, op_index) in operations:
        print(f"Operation {op_index} of Job {job} starts at {s[(job, op_index)].X}")
else:
    print("No optimal solution found")
