import gurobipy as gp
from gurobipy import GRB

# Create model
model = gp.Model("FleetAssignment")

# Sets
P = [0, 1, 2]  # Plane types
L = [0, 1]     # Locations
T = [1, 2]     # Time periods

# Parameters
capacity = {0: 80, 1: 89, 2: 81}
cost = {0: 7, 1: 6, 2: 6}
demand = {
    (0, 1, 2): 20,
    (1, 0, 1): 23
}
max_deploy = {
    (0, 0, 1, 1): 0,
    (0, 0, 1, 2): 2,
    (1, 1, 0, 1): 2,
    (2, 1, 0, 1): 2
}

# Decision variables
x = model.addVars(P, L, L, T, vtype=GRB.INTEGER, name="x")
y = model.addVars(P, L, T, vtype=GRB.INTEGER, name="y")

# Objective: Minimize total cost
model.setObjective(gp.quicksum(cost[p] * x[p, l1, l2, t] for p in P for l1 in L for l2 in L for t in T), GRB.MINIMIZE)

# Constraints
# Demand satisfaction
for l1 in L:
    for l2 in L:
        for t in T:
            if (l1, l2, t) in demand:
                model.addConstr(gp.quicksum(capacity[p] * x[p, l1, l2, t] for p in P) >= demand[l1, l2, t], 
                               f"demand_{l1}_{l2}_{t}")

# Fleet balance (Period 1)
for p in P:
    for l in L:
        model.addConstr(y[p, l, 1] + gp.quicksum(x[p, l, l2, 1] for l2 in L) <= 2, f"balance_p1_{p}_{l}")

# Fleet balance (Period 2)
for p in P:
    for l in L:
        model.addConstr(y[p, l, 2] == y[p, l, 1] + gp.quicksum(x[p, l2, l, 1] for l2 in L) - 
                        gp.quicksum(x[p, l, l2, 1] for l2 in L), f"balance_p2_{p}_{l}")

# Route restrictions
for p in P:
    for l1 in L:
        for l2 in L:
