model = gp.Model("SupplyChainOptimization")

# Sets
L = [0, 1, 2]
K = [0, 1]
R = [(0,1), (1,0), (1,2), (2,0), (2,1)]

# Parameters
c = {
    (0,1): {0: 11, 1: 0},   # No commodity 1 flow on (0,1)
    (1,0): {0: 33, 1: 18},
    (1,2): {0: 0, 1: 18},   # No commodity 0 flow on (1,2)
    (2,0): {0: 22, 1: 18},
    (2,1): {0: 22, 1: 18}
}

f = {
    (0,1): 957,
    (1,0): 891,
    (1,2): 887,
    (2,0): 853,
    (2,1): 855
}

s = {
    (0,1): 644,
    (1,0): 553,
    (1,2): 552,
    (2,0): 551,
    (2,1): 618
}

b = {
    0: {0: 1, 1: 0},
    1: {0: 0, 1: 1},
    2: {0: -1, 1: -1}
}

# Decision Variables
x = {}
for (i,j) in R:
    for k in K:
        x[i,j,k] = model.addVar(lb=0, ub=1, vtype=GRB.CONTINUOUS, name=f"x_{i}_{j}_{k}")

y = {}
for (i,j) in R:
    y[i,j] = model.addVar(lb=0, vtype=GRB.INTEGER, name=f"y_{i}_{j}")

# Objective Function
model.setObjective(
    gp.quicksum(c[i,j][k] * x[i,j,k] for (i,j) in R for k in K) +
    gp.quicksum(f[i,j] * y[i,j] for (i,j) in R),
    GRB.MINIMIZE
)

# Constraints
# Flow Conservation
for i in L:
    for k in K:
        model.addConstr(
            gp.quicksum(x[j,i,k] for j in L if (j,i) in R) -
            gp.quicksum(x[i,j,k] for j in L if (i,j) in R) == b[i][k],
            name=f"flow_conservation_{i}_{k}"
        )

# Capacity Constraints
for (i,j) in R:
    model.addConstr(
        gp.quicksum(x[i,j,k] for k in K) <= s[i,j] * y[i,j],
        name=f"capacity_{i}_{j}"
    )

# Optimize the model
model.optimize()

# Print the solution
