    print("Optimal Solution Found:")
    for (i,j) in R:
        print(f"Facilities on route ({i},{j}): {y[i,j].X}")
        for k in K:
            print(f"Flow of commodity {k} on route ({i},{j}): {x[i,j,k].X}")
    print(f"Total Cost: {model.ObjVal}")
else:
    print("No optimal solution found.")
