    for j in C:
        if i != j:
            x[i, j] = model.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")

p = {}
for i in C:
    if i == 0:
        p[i] = model.addVar(lb=-GRB.INFINITY, ub=GRB.INFINITY, vtype=GRB.INTEGER, name=f"p_{i}")
    else:
        p[i] = model.addVar(lb=1, ub=4, vtype=GRB.INTEGER, name=f"p_{i}")

# Objective function
