    model.addConstr(
        gp.quicksum(x[i, j] for j in C if i != j) == 1,
        name=f"outgoing_{i}"
    )

# Each city must be visited exactly once (incoming route)
for j in C:
    model.addConstr(
        gp.quicksum(x[i, j] for i in C if i != j) == 1,
        name=f"incoming_{j}"
    )

