model = gp.Model("Generator_Optimization")

# Sets
T = [0, 1, 2, 3, 4]  # Time periods
G = [0, 1]           # Generator types

# Parameters
BaseCost = {0: 78, 1: 79}
VarCost = {0: 4, 1: 3}
StartupCost = {0: 348, 1: 353}
Demand = {0: 184, 1: 208, 2: 166, 3: 214, 4: 216}
MinOutput = {0: 35, 1: 34}
MaxOutput = {0: 129, 1: 128}
TotalMaxOutput = {0: 211.6, 1: 239.2, 2: 190.9, 3: 246.1, 4: 248.4}
MaxActive = {0: 5, 1: 5}

# Decision variables
active = model.addVars(G, T, vtype=GRB.INTEGER, name="active")
output = model.addVars(G, T, vtype=GRB.CONTINUOUS, name="output")
startup = model.addVars(G, T, vtype=GRB.INTEGER, name="startup")

# Objective function
model.setObjective(
    gp.quicksum(
        BaseCost[g] * active[g, t] + VarCost[g] * output[g, t] + StartupCost[g] * startup[g, t]
        for g in G for t in T
    ),
    GRB.MINIMIZE
)

# Constraints
# Demand satisfaction
for t in T:
    model.addConstr(
        gp.quicksum(output[g, t] for g in G) >= Demand[t],
        f"Demand_{t}"
    )

# Generator output bounds
for g in G:
    for t in T:
        model.addConstr(
            output[g, t] >= MinOutput[g] * active[g, t],
            f"MinOutput_{g}_{t}"
        )
        model.addConstr(
            output[g, t] <= MaxOutput[g] * active[g, t],
            f"MaxOutput_{g}_{t}"
        )

# Total maximum output
for t in T:
    model.addConstr(
        gp.quicksum(MaxOutput[g] * active[g, t] for g in G) >= TotalMaxOutput[t],
        f"TotalMaxOutput_{t}"
    )

# Active generator limit
for g in G:
    for t in T:
        model.addConstr(
            active[g, t] <= MaxActive[g],
            f"MaxActive_{g}_{t}"
        )

# Startup logic
for g in G:
    model.addConstr(
        startup[g, 0] <= active[g, 0],
        f"Startup_Initial_{g}"
    )
    for t in T[1:]:
        model.addConstr(
            startup[g, t] <= active[g, t] - active[g, t-1],
            f"Startup_{g}_{t}"
        )

