supply = {
    (0, 0): 1, (0, 1): -1,
    (1, 0): 0, (1, 1): -1,
    (2, 0): -1, (2, 1): 2
}
cost = 5
combined_capacity = 122

# Individual product capacities (i, j, p): capacity
capacity = {
    (0, 1, 0): 71, (0, 1, 1): 74,
    (0, 2, 0): 70, (0, 2, 1): 74,
    (1, 0, 0): 75, (1, 0, 1): 74,
    (1, 2, 0): 72, (1, 2, 1): 73,
    (2, 0, 0): 71, (2, 0, 1): 70,
    (2, 1, 0): 71, (2, 1, 1): 73
}

# Decision variables
x = model.addVars([(i, j, p) for i in C for j in C for p in P], lb=0, name="x")

# Objective: Minimize total shipping cost
model.setObjective(gp.quicksum(cost * x[i, j, p] for i in C for j in C for p in P), GRB.MINIMIZE)

