    0: {0: 78, 1: 64, 2: 61, 3: 54},
    1: {0: 78, 1: 61, 2: 70, 3: 70},
    2: {0: 57, 1: 74, 2: 58, 3: 50}
}

# Capacity
CAP = {0: 826, 1: 890, 2: 853, 3: 812}

# Resource consumption
R = {0: 1.752, 1: 1.637, 2: 1.524}

# Production limits
PL = {
    0: {0: 257, 1: 179, 2: 115, 3: 54},
    1: {0: 279, 1: 201, 2: 140, 3: 70},
    2: {0: 239, 1: 182, 2: 108, 3: 50}
}

# Model
model = gp.Model("Production_Planning")

# Decision variables
y = {}
x = {}
I = {}
for p in products:
    for t in months:
        y[p, t] = model.addVar(vtype=GRB.BINARY, name=f"y_{p}_{t}")
        x[p, t] = model.addVar(vtype=GRB.CONTINUOUS, name=f"x_{p}_{t}")
        I[p, t] = model.addVar(vtype=GRB.CONTINUOUS, name=f"I_{p}_{t}")

# Objective: Minimize total cost
model.setObjective(
    gp.quicksum(S[p][t] * y[p, t] + C[p][t] * x[p, t] + H[p][t] * I[p, t] 
                for p in products for t in months),
    GRB.MINIMIZE
)

