# Sets
products = [0, 1]
cities = [0, 1, 2]

# Parameters
cost = 5
demand = {
    (0, 0): -2, (0, 1): -3,
    (1, 0): 2, (1, 1): 1,
    (2, 0): 0, (2, 1): 2
}
joint_capacity = 122
individual_capacity = {
    (0, 1, 0): 74, (0, 1, 1): 73,
    (0, 2, 0): 72, (0, 2, 1): 72,
    (1, 0, 0): 72, (1, 0, 1): 70,
    (1, 2, 0): 71, (1, 2, 1): 70,
    (2, 0, 0): 74, (2, 0, 1): 74,
    (2, 1, 0): 72, (2, 1, 1): 71
}

# Decision variables
x = model.addVars(
    [(i, j, p) for i in cities for j in cities for p in products],
    lb=0, name="x"
)

# Objective function
model.setObjective(
    gp.quicksum(cost * x[i, j, p] for i in cities for j in cities for p in products),
    sense=GRB.MINIMIZE
)

# Constraints
# Supply-demand balance
for c in cities:
    for p in products:
        model.addConstr(
            gp.quicksum(x[i, c, p] for i in cities) - gp.quicksum(x[c, j, p] for j in cities) == demand[c, p],
            name=f"balance_{c}_{p}"
        )

# Joint capacity
for i in cities:
    for j in cities:
        model.addConstr(
            gp.quicksum(x[i, j, p] for p in products) <= joint_capacity,
            name=f"joint_capacity_{i}_{j}"
        )

# Individual product capacity
for i in cities:
    for j in cities:
        for p in products:
            model.addConstr(
                x[i, j, p] <= individual_capacity.get((i, j, p), 0),
                name=f"ind_capacity_{i}_{j}_{p}"
            )

# Solve
