for g in G:
    for t in T:
        x[g, t] = model.addVar(vtype=GRB.INTEGER, lb=0, name=f"x_{g}_{t}")
        y[g, t] = model.addVar(lb=min_output, ub=max_output[g], name=f"y_{g}_{t}")
        s[g, t] = model.addVar(vtype=GRB.INTEGER, lb=0, name=f"s_{g}_{t}")

# Objective Function
total_cost = gp.quicksum(
    base_cost * x[g, t] + production_cost * x[g, t] * y[g, t] + startup_cost[g] * s[g, t]
    for g in G for t in T
)
model.setObjective(total_cost, GRB.MINIMIZE)

