import gurobipy as gp
from gurobipy import GRB

# Create model
model = gp.Model("PowerGeneration")

# Sets
T = [0, 1, 2, 3, 4]
G = [0, 1]

# Parameters
BaseCost = {0: 77, 1: 76}
VarCost = {0: 3, 1: 4}
StartupCost = {0: 367, 1: 369}
Demand = {0: 186, 1: 185, 2: 249, 3: 228, 4: 156}
MinOutput = {0: 41, 1: 47}
MaxOutput = {0: 135, 1: 150}
MaxActive = {0: 5, 1: 4}
MaxStartup = {0: 4, 1: 1}

# Decision variables
active = model.addVars(G, T, vtype=GRB.INTEGER, name="active")
output = model.addVars(G, T, vtype=GRB.CONTINUOUS, name="output")
startup = model.addVars(G, T, vtype=GRB.INTEGER, name="startup")

# Objective function
model.setObjective(
    gp.quicksum(
        BaseCost[g] * active[g, t] + VarCost[g] * output[g, t] + StartupCost[g] * startup[g, t]
        for g in G for t in T
    ),
    GRB.MINIMIZE
)

# Constraints
# Demand satisfaction
for t in T:
    model.addConstr(gp.quicksum(output[g, t] for g in G) >= Demand[t], f"Demand_{t}")

# Generator output bounds
for g in G:
    for t in T:
        model.addConstr(output[g, t] >= MinOutput[g] * active[g, t], f"MinOutput_{g}_{t}")
        model.addConstr(output[g, t] <= MaxOutput[g] * active[g, t], f"MaxOutput_{g}_{t}")

# Maximum active generators
for g in G:
    for t in T:
        model.addConstr(active[g, t] <= MaxActive[g], f"MaxActive_{g}_{t}")

# Capacity reserve
for t in T:
    model.addConstr(
        gp.quicksum(MaxOutput[g] * active[g, t] for g in G) >= 1.15 * Demand[t],
        f"Reserve_{t}"
    )

# Startup constraints for period 0
for g in G:
    model.addConstr(startup[g, 0] <= MaxStartup[g], f"Startup_{g}_0")

# Startup constraints for t > 0
for g in G:
    for t in T[1:]:
        model.addConstr(startup[g, t] <= active[g, t-1], f"Startup_{g}_{t}")

# Solve
model.optimize()

# Output results
if model.status == GRB.OPTIMAL:
    print("Optimal solution found.")
    for t in T:
        print(f"Period {t}:")
        for g in G:
            print(f"  Type {g}: Active={active[g, t].X}, Output={output[g, t].X}, Startup={startup[g, t].X}")
    print(f"Total Cost: {model.objVal}")
else:
    print("No optimal solution found.")
```

