import gurobipy as gp
from gurobipy import GRB

# Create model
model = gp.Model("PlaneDeployment")

# Sets
P = [0, 1, 2]  # Plane types
L = [0, 1]     # Locations

# Parameters
capacity = {0: 81, 1: 83, 2: 91}
cost = {0: 5, 1: 6, 2: 8}
demand = {(0, 1): 26, (1, 0): 3}
max_fleet = {p: 2 for p in P}
max_route = {p: 2 for p in P}

# Decision Variables
x = model.addVars(P, L, L, vtype=GRB.INTEGER, name="x")
y = model.addVars(P, L, vtype=GRB.INTEGER, name="y")

# Objective Function
model.setObjective(
    gp.quicksum(cost[p] * x[p, l, l_prime] for p in P for l in L for l_prime in L),
    sense=GRB.MINIMIZE
)

# Constraints
# Fleet Availability
model.addConstrs(
    (gp.quicksum(x[p, l, l_prime] for l in L for l_prime in L) + gp.quicksum(y[p, l] for l in L) <= max_fleet[p]
     for p in P),
    name="fleet_availability"
)

# Route Restrictions
model.addConstrs(
    (x[p, l, l_prime] <= max_route[p] for p in P for l in L for l_prime in L),
    name="route_restrictions"
)

# Demand Satisfaction
model.addConstr(
    gp.quicksum(capacity[p] * x[p, 0, 1] for p in P) >= demand[(0, 1)],
    name="demand_01"
)
model.addConstr(
    gp.quicksum(capacity[p] * x[p, 1, 0] for p in P) >= demand[(1, 0)],
    name="demand_10"
)

# Location Balance (assuming initial_idle is equal to max_fleet)
model.addConstrs(
    (y[p, 0] + gp.quicksum(x[p, 0, l_prime] for l_prime in L) == max_fleet[p] for p in P),
    name="location_balance_0"
)
model.addConstrs(
    (y[p, 1] + gp.quicksum(x[p, 1, l_prime] for l_prime in L) == max_fleet[p] for p in P),
    name="location_balance_1"
)

# Solve the model
model.optimize()

# Print solution
if model.status == GRB.OPTIMAL:
    print("Optimal solution found:")
    for p in P:
        for l in L:
            for l_prime in L:
                if x[p, l, l_prime].x > 0:
                    print(f"Deploy {x[p, l, l_prime].x} Plane {p} from Location {l} to {l_prime}")
    for p in P:
        for l in L:
            if y[p, l].x > 0:
                print(f"Idle {y[p, l].x} Plane {p} at Location {l}")
    print(f"Total Cost: {model.objVal}")
else:
    print("No optimal solution found")
```

