from gurobipy import GRB

# Create the model
model = gp.Model("TSP")

# Cities
C = [0, 1, 2, 3, 4, 5]
n = len(C)

# Distances (d[i][j] = distance from city i to city j)
d = {
    0: {0: 0, 1: 154, 2: 166, 3: 152, 4: 169, 5: 161},
    1: {0: 156, 1: 0, 2: 158, 3: 155, 4: 162, 5: 169},
    2: {0: 162, 1: 168, 2: 0, 3: 152, 4: 156, 5: 156},
    3: {0: 162, 1: 163, 2: 166, 3: 0, 4: 158, 5: 155},
    4: {0: 162, 1: 150, 2: 151, 3: 170, 4: 0, 5: 163},
    5: {0: 152, 1: 167, 2: 159, 3: 169, 4: 159, 5: 0}
}

# Decision variables
x = {}
for i in C:
    for j in C:
        if i != j:
            x[i, j] = model.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")

u = {}
for i in C:
    u[i] = model.addVar(vtype=GRB.INTEGER, name=f"u_{i}")

# Objective function
model.setObjective(gp.quicksum(d[i][j] * x[i, j] for i in C for j in C if i != j), GRB.MINIMIZE)

# Constraints
# Each city has exactly one incoming route
for j in C:
    model.addConstr(gp.quicksum(x[i, j] for i in C if i != j) == 1, name=f"incoming_{j}")

# Each city has exactly one outgoing route
for i in C:
    model.addConstr(gp.quicksum(x[i, j] for j in C if j != i) == 1, name=f"outgoing_{i}")

# Subtour elimination constraints
for i in C:
    for j in C:
        if i != j and i != 0 and j != 0:
            model.addConstr(u[i] - u[j] + n * x[i, j] <= n - 1, name=f"subtour_{i}_{j}")

# Position variable bounds
for i in C:
    model.addConstr(u[i] >= 0, name=f"u_{i}_min")
    model.addConstr(u[i] <= n - 1, name=f"u_{i}_max")

# Starting city is fixed at position 0
model.addConstr(u[0] == 0, name="u_0_fixed")

# Optimize the model
model.optimize()

# Print the solution
if model.status == GRB.OPTIMAL:
    print("Optimal tour:")
    for i in C:
        for j in C:
            if i != j and x[i, j].x > 0.5:
                print(f"From city {i} to city {j}: distance {d[i][j]}")
    print(f"Total distance: {model.objVal}")
else:
    print("No solution found")
