model = gp.Model("PowerGeneration")

# Sets
T = [0, 1, 2]  # Time periods
G = [0, 1, 2]  # Generator types

# Parameters
BaseCost = {0: 86, 1: 90, 2: 86}
PerMWCost = {0: 2, 1: 2, 2: 3}
StartupCost = {0: 396, 1: 382, 2: 384}
Demand = {0: 197, 1: 199, 2: 199}
MinOutput = {0: 30, 1: 29, 2: 29}
MaxOutput = {0: 146, 1: 148, 2: 145}
CapacityReserve = {0: 226.55, 1: 228.85, 2: 228.85}
MaxGenerators = {0: 5, 1: 5, 2: 5}
MaxStartup = {0: 3, 1: 1, 2: 4}

# Decision Variables
x = model.addVars(G, T, vtype=GRB.INTEGER, name="x")
y = model.addVars(G, T, vtype=GRB.CONTINUOUS, name="y")
z = model.addVars(G, T, vtype=GRB.INTEGER, name="z")

# Objective Function
model.setObjective(
    gp.quicksum(
        BaseCost[g] * x[g, t] + PerMWCost[g] * y[g, t] + StartupCost[g] * z[g, t]
        for g in G for t in T
    ),
    GRB.MINIMIZE
)

# Constraints
# Power Demand
for t in T:
    model.addConstr(gp.quicksum(y[g, t] for g in G) >= Demand[t], f"Demand_{t}")

# Capacity Reserve
for t in T:
    model.addConstr(
        gp.quicksum(MaxOutput[g] * x[g, t] for g in G) >= CapacityReserve[t],
        f"Reserve_{t}"
    )

# Generator Output Limits
for g in G:
    for t in T:
        model.addConstr(y[g, t] >= MinOutput[g] * x[g, t], f"MinOutput_{g}_{t}")
        model.addConstr(y[g, t] <= MaxOutput[g] * x[g, t], f"MaxOutput_{g}_{t}")

# Generator Availability
for g in G:
    for t in T:
        model.addConstr(x[g, t] <= MaxGenerators[g], f"MaxGenerators_{g}_{t}")

# Startup Constraints
for g in G:
    model.addConstr(z[g, 0] <= MaxStartup[g], f"MaxStartup_{g}_0")
    for t in [1, 2]:
        model.addConstr(z[g, t] <= x[g, t] - x[g, t-1], f"Startup_{g}_{t}")

# Optimize
model.optimize()

