u = {
    0: {1: 8, 2: 7, 3: 8, 4: 6},
    1: {0: 5, 2: 9, 3: 9, 4: 9},
    2: {0: 9, 1: 10, 3: 5, 4: 5},
    3: {0: 10, 1: 8, 2: 6, 4: 10},
