import gurobipy as gp
from gurobipy import GRB

# Define the cities and costs
cities = [0, 1, 2, 3, 4, 5]
n = len(cities)

# Cost matrix (cost[i][j] = cost from city i to city j)
cost = {
    0: {1: 158, 2: 169, 3: 160, 4: 160, 5: 162},
    1: {0: 156, 2: 165, 3: 162, 4: 151, 5: 153},
    2: {0: 155, 1: 167, 3: 165, 4: 166, 5: 154},
    3: {0: 161, 1: 155, 2: 168, 4: 167, 5: 167},
    4: {0: 159, 1: 158, 2: 165, 3: 161, 5: 170},
    5: {0: 159, 1: 161, 2: 157, 3: 162, 4: 161},
}

# Create model
model = gp.Model("TSP_Position_Based")

# Decision variables: x[i,j] = 1 if arc (i,j) is used
x = {}
for i in cities:
    for j in cities:
        if i != j:
            x[i, j] = model.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")

# Position variables: u[i] = position of city i in the tour
u = {}
for i in cities:
    u[i] = model.addVar(vtype=GRB.INTEGER, name=f"u_{i}")

# Objective: minimize total cost
model.setObjective(
    gp.quicksum(cost[i][j] * x[i, j] for i in cities for j in cities if i != j),
    GRB.MINIMIZE
)

# Constraints
# 1. Each city is entered exactly once
for j in cities:
    model.addConstr(
        gp.quicksum(x[i, j] for i in cities if i != j) == 1,
        name=f"enter_{j}"
    )

# 2. Each city is exited exactly once
for i in cities:
    model.addConstr(
        gp.quicksum(x[i, j] for j in cities if j != i) == 1,
        name=f"exit_{i}"
    )

# 3. Subtour elimination (position constraints)
for i in cities:
    for j in cities:
        if i != j and i != 0 and j != 0:
            model.addConstr(
                u[i] - u[j] + n * x[i, j] <= n - 1,
                name=f"subtour_{i}_{j}"
            )

# 4. Starting city position
model.addConstr(u[0] == 0, name="start_pos")

# 5. Position bounds for other cities
for i in cities:
    if i != 0:
        model.addConstr(u[i] >= 1, name=f"pos_lb_{i}")
        model.addConstr(u[i] <= n - 1, name=f"pos_ub_{i}")

# Solve the model
model.optimize()

# Print solution
if model.status == GRB.OPTIMAL:
    print("Optimal route found with total cost:", model.objVal)
    print("Route:")
    tour = [0]  # Start at city 0
    current_city = 0
    for _ in range(n - 1):
        for j in cities:
            if j != current_city and x[current_city, j].x > 0.5:
                tour.append(j)
                current_city = j
                break
    tour.append(0)  # Return to city 0
    print(" -> ".join(map(str, tour)))
else:
    print("No optimal solution found.")
