import gurobipy as gp
from gurobipy import GRB

# Sets
employees = [0, 1, 2, 3, 4, 5, 6]
projects = [0, 1, 2, 3, 4, 5, 6, 7]

# Parameters
cost = {
    0: {0: 30, 1: 40, 2: 40, 3: 39, 4: 37, 5: 40, 6: 47, 7: 35},
    1: {0: 30, 1: 49, 2: 42, 3: 40, 4: 50, 5: 37, 6: 32, 7: 36},
    2: {0: 47, 1: 49, 2: 30, 3: 48, 4: 49, 5: 31, 6: 33, 7: 39},
    3: {0: 38, 1: 31, 2: 34, 3: 33, 4: 50, 5: 30, 6: 49, 7: 35},
    4: {0: 43, 1: 37, 2: 33, 3: 40, 4: 33, 5: 44, 6: 37, 7: 47},
    5: {0: 36, 1: 48, 2: 39, 3: 50, 4: 41, 5: 39, 6: 49, 7: 43},
    6: {0: 45, 1: 43, 2: 44, 3: 30, 4: 35, 5: 38, 6: 37, 7: 40}
}

hours_limit = {
    0: {0: 10, 1: 10, 2: 9, 3: 12, 4: 7, 5: 12, 6: 9, 7: 10},
    1: {0: 8, 1: 12, 2: 7, 3: 9, 4: 11, 5: 11, 6: 8, 7: 10},
    2: {0: 7, 1: 9, 2: 12, 3: 9, 4: 12, 5: 12, 6: 12, 7: 10},
    3: {0: 9, 1: 9, 2: 11, 3: 12, 4: 8, 5: 12, 6: 8, 7: 9},
    4: {0: 9, 1: 11, 2: 9, 3: 7, 4: 8, 5: 7, 6: 12, 7: 9},
    5: {0: 10, 1: 11, 2: 9, 3: 11, 4: 11, 5: 10, 6: 10, 7: 11},
    6: {0: 7, 1: 9, 2: 11, 3: 9, 4: 12, 5: 12, 6: 11, 7: 7}
}

employee_capacity = {0: 16, 1: 19, 2: 18, 3: 25, 4: 17, 5: 16, 6: 19}
project_requirement = {0: 0, 1: 3, 2: 22, 3: 25, 4: 16, 5: 22, 6: 22, 7: 20}

# Model
model = gp.Model("WorkforceAllocation")

# Decision Variables
x = model.addVars(employees, projects, name="x")

# Objective: Minimize total cost
model.setObjective(gp.quicksum(cost[e][p] * x[e, p] for e in employees for p in projects), GRB.MINIMIZE)

# Constraints
# Project requirements
for p in projects:
    model.addConstr(gp.quicksum(x[e, p] for e in employees) == project_requirement[p], f"ProjectReq_{p}")

# Employee capacities
for e in employees:
    model.addConstr(gp.quicksum(x[e, p] for p in projects) <= employee_capacity[e], f"EmployeeCap_{e}")

# Assignment limits
for e in employees:
    for p in projects:
        model.addConstr(x[e, p] <= hours_limit[e][p], f"AssignLimit_{e}_{p}")

# Solve
model.optimize()

# Print solution
if model.status == GRB.OPTIMAL:
    print("Optimal solution found. Total cost:", model.objVal)
    for e in employees:
        for p in projects:
            if x[e, p].x > 0:
                print(f"Person {e} works {x[e, p].x} hours on Project {p}")
else:
    print("No optimal solution found.")
